\COPY (SELECT la.as_of_year, la.respondent_id, ag.agency_name, ag.agency_abbr, la.agency_code, lt.loan_type_name, la.loan_type, pt.property_type_name, la.property_type, lp.loan_purpose_name, la.loan_purpose, oo.owner_occupancy_name, la.owner_occupancy, la.loan_amount_000s, pr.preapproval_name, la.preapproval, act.action_taken_name, la.action_taken, ms.msamd_name, loc.msamd, st.state_name, st.state_abbr, loc.state_code, co.county_name, loc.county_code, loc.census_tract_number, ae.applicant_ethnicity_name, la.applicant_ethnicity, ce.co_applicant_ethnicity_name, la.co_applicant_ethnicity, ar1r.race_name AS applicant_race_name_1, ar1.race_code AS applicant_race_1, ar2r.race_name AS applicant_race_name_2, ar2.race_code AS applicant_race_2, ar3r.race_name AS applicant_race_name_3, ar3.race_code AS applicant_race_3, ar4r.race_name AS applicant_race_name_4, ar4.race_code AS applicant_race_4, ar5r.race_name AS applicant_race_name_5, ar5.race_code AS applicant_race_5, cr1r.race_name AS co_applicant_race_name_1, cr1.race_code AS co_applicant_race_1, cr2r.race_name AS co_applicant_race_name_2, cr2.race_code AS co_applicant_race_2, cr3r.race_name AS co_applicant_race_name_3, cr3.race_code AS co_applicant_race_3, cr4r.race_name AS co_applicant_race_name_4, cr4.race_code AS co_applicant_race_4, cr5r.race_name AS co_applicant_race_name_5, cr5.race_code AS co_applicant_race_5, aps.applicant_sex_name, la.applicant_sex, cs.co_applicant_sex_name, la.co_applicant_sex, la.applicant_income_000s, pur.purchaser_type_name, la.purchaser_type, dr1r.denial_reason_name AS denial_reason_name_1, dr1.denial_reason_code AS denial_reason_1, dr2r.denial_reason_name AS denial_reason_name_2, dr2.denial_reason_code AS denial_reason_2, dr3r.denial_reason_name AS denial_reason_name_3, dr3.denial_reason_code AS denial_reason_3, la.rate_spread, hs.hoepa_status_name, la.hoepa_status, ls.lien_status_name, la.lien_status, es.edit_status_name, la.edit_status, la.sequence_number, loc.population, loc.minority_population, loc.hud_median_family_income, loc.tract_to_msamd_income, loc.number_of_owner_occupied_units, loc.number_of_1_to_4_family_units, la.application_date_indicator FROM LoanApplication la JOIN Agency ag ON la.agency_code = ag.agency_code JOIN LoanType lt ON la.loan_type = lt.loan_type JOIN PropertyType pt ON la.property_type = pt.property_type JOIN LoanPurpose lp ON la.loan_purpose = lp.loan_purpose JOIN OwnerOccupancy oo ON la.owner_occupancy = oo.owner_occupancy JOIN Preapproval pr ON la.preapproval = pr.preapproval JOIN ActionTaken act ON la.action_taken = act.action_taken JOIN Location loc ON la.location_id = loc.location_id JOIN ApplicantEthnicity ae ON la.applicant_ethnicity = ae.applicant_ethnicity JOIN CoApplicantEthnicity ce ON la.co_applicant_ethnicity = ce.co_applicant_ethnicity JOIN ApplicantSex aps ON la.applicant_sex = aps.applicant_sex JOIN CoApplicantSex cs ON la.co_applicant_sex = cs.co_applicant_sex JOIN PurchaserType pur ON la.purchaser_type = pur.purchaser_type JOIN HOEPAStatus hs ON la.hoepa_status = hs.hoepa_status JOIN LienStatus ls ON la.lien_status = ls.lien_status LEFT JOIN EditStatus es ON la.edit_status = es.edit_status LEFT JOIN State st ON loc.state_code = st.state_code LEFT JOIN County co ON loc.county_code = co.county_code LEFT JOIN MSAMD ms ON loc.msamd = ms.msamd LEFT JOIN ApplicantRace ar1 ON la.id = ar1.application_id AND ar1.race_number = 1 LEFT JOIN Race ar1r ON ar1.race_code = ar1r.race_code LEFT JOIN ApplicantRace ar2 ON la.id = ar2.application_id AND ar2.race_number = 2 LEFT JOIN Race ar2r ON ar2.race_code = ar2r.race_code LEFT JOIN ApplicantRace ar3 ON la.id = ar3.application_id AND ar3.race_number = 3 LEFT JOIN Race ar3r ON ar3.race_code = ar3r.race_code LEFT JOIN ApplicantRace ar4 ON la.id = ar4.application_id AND ar4.race_number = 4 LEFT JOIN Race ar4r ON ar4.race_code = ar4r.race_code LEFT JOIN ApplicantRace ar5 ON la.id = ar5.application_id AND ar5.race_number = 5 LEFT JOIN Race ar5r ON ar5.race_code = ar5r.race_code LEFT JOIN CoApplicantRace cr1 ON la.id = cr1.application_id AND cr1.race_number = 1 LEFT JOIN Race cr1r ON cr1.race_code = cr1r.race_code LEFT JOIN CoApplicantRace cr2 ON la.id = cr2.application_id AND cr2.race_number = 2 LEFT JOIN Race cr2r ON cr2.race_code = cr2r.race_code LEFT JOIN CoApplicantRace cr3 ON la.id = cr3.application_id AND cr3.race_number = 3 LEFT JOIN Race cr3r ON cr3.race_code = cr3r.race_code LEFT JOIN CoApplicantRace cr4 ON la.id = cr4.application_id AND cr4.race_number = 4 LEFT JOIN Race cr4r ON cr4.race_code = cr4r.race_code LEFT JOIN CoApplicantRace cr5 ON la.id = cr5.application_id AND cr5.race_number = 5 LEFT JOIN Race cr5r ON cr5.race_code = cr5r.race_code LEFT JOIN ApplicationDenialReason dr1 ON la.id = dr1.application_id AND dr1.reason_number = 1 LEFT JOIN DenialReason dr1r ON dr1.denial_reason_code = dr1r.denial_reason_code LEFT JOIN ApplicationDenialReason dr2 ON la.id = dr2.application_id AND dr2.reason_number = 2 LEFT JOIN DenialReason dr2r ON dr2.denial_reason_code = dr2r.denial_reason_code LEFT JOIN ApplicationDenialReason dr3 ON la.id = dr3.application_id AND dr3.reason_number = 3 LEFT JOIN DenialReason dr3r ON dr3.denial_reason_code = dr3r.denial_reason_code ORDER BY la.id) TO '/tmp/hmda_report.csv' WITH CSV HEADER;
